16	// Service orchestrates worktree operations over a Git backend and a Prompter.
17	// out receives user-facing diagnostics (typically stderr).
18	type Service struct {
19		git    Git
20		prompt Prompter
21		out    io.Writer
22	}
23	
24	// NewService returns a Service backed by the given Git, Prompter, and
25	// diagnostics writer.
26	func NewService(git Git, prompt Prompter, out io.Writer) *Service {
27		return &Service{git: git, prompt: prompt, out: out}
28	}
29	
30	const (
31		worktreesDir   = ".worktrees"
32		mainStartPoint = "origin/main"
33	)
34	
35	// CreateOptions selects how a worktree should be created.
36	type CreateOptions struct {
37		Branch         string
38		ExistingBranch bool
39	}
40	
41	// Create makes a new worktree at <main-root>/.worktrees/<sanitized-branch>,
42	// copies configured files in, optionally trusts mise, and creates a tmp/ dir.
43	// It returns the absolute worktree path.
44	func (s *Service) Create(ctx context.Context, opts CreateOptions) (string, error) {
45		root, err := s.git.MainRoot(ctx)
46		if err != nil {
47			return "", err
48		}
49		path := filepath.Join(root, worktreesDir, worktreeDirName(opts.Branch))
50		switch _, err := os.Stat(path); {
51		case err == nil:
52			return "", fmt.Errorf("worktree already exists at %s", path)
53		case !errors.Is(err, fs.ErrNotExist):
54			return "", fmt.Errorf("check worktree path %s: %w", path, err)
55		}
56		cfg, err := LoadConfig(root)
57		if err != nil {
58			return "", err
59		}
60		files, err := s.includedFiles(ctx, root, cfg.IncludePatterns)
61		if err != nil {
62			return "", err
63		}
64		if opts.ExistingBranch {
65			if err := s.addExistingBranchWorktree(ctx, root, path, opts.Branch); err != nil {
66				return "", err
67			}
68		} else {
69			if err := s.git.FetchOriginBranch(ctx, root, "main"); err != nil {
70				return "", err
71			}
72			if err := s.git.AddWorktree(ctx, root, path, opts.Branch, mainStartPoint); err != nil {
73				return "", err
74			}
75		}
76		s.copyFiles(root, path, files)
77		if s.git.MiseTrusted(ctx, root) {
78			if err := s.git.MiseTrust(ctx, path); err != nil {
79				_, _ = fmt.Fprintf(s.out, "warning: mise trust failed: %v\n", err)
80			}
81		}
82		if err := os.MkdirAll(filepath.Join(path, "tmp"), 0o750); err != nil {
83			return "", fmt.Errorf("create tmp dir: %w", err)
84		}
85		return path, nil
86	}
87	
88	func worktreeDirName(branch string) string {
89		return strings.ReplaceAll(branch, "/", "-")
90	}
91	
92	func (s *Service) addExistingBranchWorktree(ctx context.Context, root, path, branch string) error {
93		exists, err := s.git.LocalBranchExists(ctx, root, branch)
94		if err != nil {
95			return err
96		}
97		if exists {
98			return s.git.AddWorktreeForBranch(ctx, root, path, branch)
99		}
100		if err := s.git.FetchOriginBranch(ctx, root, branch); err != nil {
101			return err
102		}
103		exists, err = s.git.OriginBranchExists(ctx, root, branch)
104		if err != nil {
105			return err
106		}
107		if !exists {
108			return fmt.Errorf("no local or origin branch found for %q", branch)
109		}
110		return s.git.AddWorktreeTrackingBranch(ctx, root, path, branch, originBranch(branch))
111	}
112	
113	func originBranch(branch string) string {
114		return "origin/" + branch
115	}
