216	// RemoveOptions selects which worktrees to remove and how.
217	type RemoveOptions struct {
218		Name  string
219		All   bool
220		Yes   bool
221		Force bool
222	}
223	
224	// Remove deletes worktrees chosen by name, by --all, or interactively. Dirty
225	// worktrees are refused unless Force is set. A confirmation prompt runs unless
226	// Yes is set.
227	func (s *Service) Remove(ctx context.Context, opts RemoveOptions) error {
228		root, err := s.git.MainRoot(ctx)
229		if err != nil {
230			return err
231		}
232		wts, err := s.git.ListWorktrees(ctx, root)
233		if err != nil {
234			return err
235		}
236		targets, err := s.selectTargets(nonMain(wts), opts)
237		if err != nil {
238			return err
239		}
240		if len(targets) == 0 {
241			_, _ = fmt.Fprintln(s.out, "No worktrees to remove.")
242			return nil
243		}
244		if !opts.Yes {
245			ok, err := s.prompt.Confirm(confirmMessage(targets))
246			if err != nil {
247				return err
248			}
249			if !ok {
250				_, _ = fmt.Fprintln(s.out, "Aborted.")
251				return nil
252			}
253		}
254		return s.removeAll(ctx, root, targets, opts.Force)
255	}
256	
257	func (s *Service) selectTargets(candidates []Worktree, opts RemoveOptions) ([]Worktree, error) {
258		switch {
259		case opts.All:
260			return candidates, nil
261		case opts.Name != "":
262			target, err := filepath.Abs(opts.Name)
263			if err != nil {
264				return nil, fmt.Errorf("resolve %q: %w", opts.Name, err)
265			}
266			var matches []Worktree
267			for _, w := range candidates {
268				if matchesRemoveTarget(w, opts.Name, target) {
269					matches = append(matches, w)
270				}
271			}
272			switch len(matches) {
273			case 0:
274				return nil, fmt.Errorf("no worktree found matching %q", opts.Name)
275			case 1:
276				return matches, nil
277			default:
278				return nil, fmt.Errorf("multiple worktrees found matching %q", opts.Name)
279			}
280		default:
281			return s.prompt.Select(candidates)
282		}
283	}
284	
285	func matchesRemoveTarget(w Worktree, name, absPath string) bool {
286		return filepath.Base(w.Path) == name || w.Path == absPath || w.Branch == name
287	}
288	
289	func (s *Service) removeAll(ctx context.Context, root string, targets []Worktree, force bool) error {
290		failed := false
291		for _, w := range targets {
292			if !force {
293				dirty, err := s.git.IsDirty(ctx, w.Path)
294				if err != nil {
295					_, _ = fmt.Fprintf(s.out, "skip %s: %v\n", w.Path, err)
296					failed = true
297					continue
298				}
299				if dirty {
300					_, _ = fmt.Fprintf(s.out, "skip %s: has uncommitted changes (use --force)\n", w.Path)
301					failed = true
302					continue
303				}
304			}
305			if err := s.git.RemoveWorktree(ctx, root, w.Path, force); err != nil {
306				_, _ = fmt.Fprintf(s.out, "failed to remove %s: %v\n", w.Path, err)
307				failed = true
308				continue
309			}
310			_, _ = fmt.Fprintf(s.out, "removed %s\n", w.Path)
311		}
312		if failed {
313			return errors.New("one or more worktrees could not be removed")
314		}
315		return nil
316	}
317	
318	func nonMain(wts []Worktree) []Worktree {
319		out := make([]Worktree, 0, len(wts))
320		for _, w := range wts {
321			if !w.IsMain {
322				out = append(out, w)
323			}
324		}
325		return out
326	}
