337	// List returns all worktrees with the Dirty flag populated.
338	func (s *Service) List(ctx context.Context) ([]Worktree, error) {
339		root, err := s.git.MainRoot(ctx)
340		if err != nil {
341			return nil, err
342		}
343		wts, err := s.git.ListWorktrees(ctx, root)
344		if err != nil {
345			return nil, err
346		}
347		for i := range wts {
348			dirty, err := s.git.IsDirty(ctx, wts[i].Path)
349			if err != nil {
350				return nil, err
351			}
352			wts[i].Dirty = dirty
353		}
354		return wts, nil
355	}
